nav_replacement = """<nav class="flex flex-col gap-1 px-space-sm mt-space-sm" data-active-classes="bg-primary-container text-on-primary-fixed font-bold rounded-xl shadow-[0_0_16px_rgba(0,229,255,0.25)]"><a aria-current="page" class="group flex items-center justify-between px-space-md py-space-sm transition-all bg-primary-container text-on-primary-fixed font-bold rounded-xl shadow-[0_0_16px_rgba(0,229,255,0.25)]" data-path="dashboard-lms" href="../makai_academy_dashboard_principal_lms_simulador_caces/code.html#resumen"><div class="flex items-center gap-space-sm"><span class="material-symbols-outlined text-xl text-primary">space_dashboard</span><span class="font-body-md text-body-md">Dashboard LMS</span></div></a><a class="group flex items-center justify-between px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-all" data-path="simulador-caces" href="../makai_academy_dashboard_principal_lms_simulador_caces/code.html#examen"><div class="flex items-center gap-space-sm"><span class="material-symbols-outlined text-xl text-primary">clinical_notes</span><span class="font-body-md text-body-md">Simulador CACES</span></div><span class="font-label-sm text-label-sm px-space-xs py-0.5 rounded bg-surface-container-high text-primary tracking-tight">ENARM/CACES</span></a><a class="group flex items-center justify-between px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-all" data-path="banco-de-preguntas" href="../makai_academy_dashboard_principal_lms_simulador_caces/code.html#resumen"><div class="flex items-center gap-space-sm"><span class="material-symbols-outlined text-xl text-primary">quiz</span><span class="font-body-md text-body-md">Banco de Preguntas</span></div><span class="font-label-sm text-label-sm text-on-surface-variant">4,250+</span></a><a class="group flex items-center justify-between px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-all" data-path="rotaciones-clinicas" href="../makai_academy_dashboard_principal_lms_simulador_caces/code.html#resumen"><div class="flex items-center gap-space-sm"><span class="material-symbols-outlined text-xl text-primary">stethoscope</span><span class="font-body-md text-body-md">Rotaciones Clínicas</span></div></a><a class="group flex items-center justify-between px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-all" data-path="repeticion-espaciada" href="../makai_academy_repetici_n_espaciada_algor_tmica/code.html"><div class="flex items-center gap-space-sm"><span class="material-symbols-outlined text-xl text-primary">style</span><span class="font-body-md text-body-md">Repetición Espaciada</span></div><span class="font-label-sm text-label-sm px-space-xs py-0.5 rounded bg-secondary/15 text-secondary">Sináptico v4.4</span></a><a class="group flex items-center justify-between px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-all" data-path="metricas-desempeno" href="../makai_academy_dashboard_principal_lms_simulador_caces/code.html#metricas"><div class="flex items-center gap-space-sm"><span class="material-symbols-outlined text-xl text-primary">ecg</span><span class="font-body-md text-body-md">Métricas &amp; Desempeño</span></div></a><a class="group flex items-center justify-between px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-all" data-path="motor-3d-uci" href="../makai_academy_motor_de_simulaci_n_cl_nica_3d_hud_uci/code.html"><div class="flex items-center gap-space-sm"><span class="material-symbols-outlined text-xl text-primary">view_in_ar</span><span class="font-body-md text-body-md">Motor 3D UCI</span></div></a><a class="group flex items-center justify-between px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-all" data-path="aula-virtual" href="../makai_academy_aula_virtual_y_visor_de_streaming/code.html"><div class="flex items-center gap-space-sm"><span class="material-symbols-outlined text-xl text-primary">school</span><span class="font-body-md text-body-md">Aula Virtual</span></div></a><a class="group flex items-center justify-between px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-all" data-path="mentoria-elite-vip" href="../makai_academy_planes_acad_micos_caces_mentor_a_lite/code.html"><div class="flex items-center gap-space-sm"><span class="material-symbols-outlined text-xl text-primary-container">stars</span><span class="font-body-md text-body-md">Mentoría Élite VIP</span></div><span class="font-label-sm text-label-sm px-space-xs py-0.5 rounded bg-primary-container/20 text-primary-fixed">VIP</span></a></nav>"""

files = [
    "stitch_makai_academy_auth_portal/makai_academy_dashboard_principal_lms_simulador_caces/code.html",
    "stitch_makai_academy_auth_portal/makai_academy_repetici_n_espaciada_algor_tmica/code.html",
    "stitch_makai_academy_auth_portal/makai_academy_motor_de_simulaci_n_cl_nica_3d_hud_uci/code.html",
    "stitch_makai_academy_auth_portal/makai_academy_aula_virtual_y_visor_de_streaming/code.html"
]

for file in files:
    with open(file, 'r') as f:
        content = f.read()

    # Use regex to find and replace the whole <nav>...</nav> tag block
    # It might contain newlines if formatted, so we use re.DOTALL
    new_content = re.sub(r'<nav[^>]*>.*?</nav>', nav_replacement, content, flags=re.DOTALL)

    # Also replace any other AnkiSync text (in text nodes or spans not caught by the nav replacement)
    new_content = new_content.replace('AnkiSync', 'Sináptico v4.4')

    with open(file, 'w') as f:
        f.write(new_content)

print("Done")
